def section_68_applicable_amount(facts):
    stipulated = facts.get('applicable_amount_under_section_68_b')
    if isinstance(stipulated, (int, float)) and not isinstance(stipulated, bool):
        return {'value': stipulated, 'used_units': ['u68_b1_qty'], 'open_dependencies': []}
    status = facts.get('filing_status')
    amounts = {
        'joint_return': 300000,
        'surviving_spouse': 300000,
        'head_of_household': 275000,
        'unmarried': 250000,
        'married_filing_separately': 150000
    }
    if status in amounts:
        return {'value': amounts[status], 'used_units': ['u68_b1_qty'], 'open_dependencies': []}
    return {'value': None, 'used_units': ['u68_b1_qty'], 'open_dependencies': ['applicable_amount_under_section_68_b or filing_status under sections 2 and 7703']}

def section_151_applicable_percentage(facts):
    threshold = section_68_applicable_amount(facts)
    agi = facts.get('adjusted_gross_income')
    units = ['u151_d3b_qty', 'u68_b1_qty']
    deps = []
    if threshold['value'] is None:
        deps.extend(threshold['open_dependencies'])
    if not isinstance(agi, (int, float)) or isinstance(agi, bool):
        deps.append('adjusted_gross_income')
    if deps:
        return {'value': None, 'used_units': units, 'open_dependencies': sorted(set(deps))}
    excess = agi - threshold['value']
    if excess <= 0:
        return {'value': 0, 'used_units': units, 'open_dependencies': []}
    separate = facts.get('taxpayer_is_married_filing_separately')
    if not isinstance(separate, bool):
        status = facts.get('filing_status')
        if status == 'married_filing_separately':
            separate = True
        elif status in ('joint_return', 'surviving_spouse', 'head_of_household', 'unmarried'):
            separate = False
    if not isinstance(separate, bool):
        return {'value': None, 'used_units': units, 'open_dependencies': ['taxpayer_is_married_filing_separately']}
    increment = 1250 if separate else 2500
    steps = int(excess / increment)
    if excess > steps * increment:
        steps += 1
    return {'value': min(100, 2 * steps), 'used_units': units, 'open_dependencies': []}

def section_151_deduction_allowable_from_exemption_entitlement(facts):
    direct = facts.get('deduction_under_section_151_allowable_to_another_taxpayer_for_subject')
    if isinstance(direct, bool):
        return {'value': direct, 'used_units': ['u151_a_pred'], 'open_dependencies': []}
    entitlement = facts.get('exemption_under_section_151_entitlement_of_another_taxpayer_for_subject')
    if entitlement is True:
        allowance = section_151_personal_exemptions_allowed_as_deductions({
            'taxpayer_is_individual': facts.get('other_taxpayer_with_exemption_entitlement_is_individual')
        })
        return {'value': allowance['value'], 'used_units': ['u151_a_pred'], 'open_dependencies': allowance['open_dependencies']}
    deps = ['deduction_under_section_151_allowable_to_another_taxpayer_for_subject']
    if not isinstance(entitlement, bool):
        deps.append('exemption_under_section_151_entitlement_of_another_taxpayer_for_subject')
    return {'value': None, 'used_units': ['u151_a_pred'], 'open_dependencies': deps}

def section_151_certain_dependent_disallowance_applies(facts):
    allowance = section_151_deduction_allowable_from_exemption_entitlement(facts)
    units = ['u151_a_pred', 'u151_d2_pred']
    return {'value': allowance['value'], 'used_units': units, 'open_dependencies': allowance['open_dependencies']}

def section_151_certain_dependent_exemption_amount(facts):
    applies = section_151_certain_dependent_disallowance_applies(facts)
    units = ['u151_a_pred', 'u151_d2_pred', 'u151_d2_qty']
    if applies['value'] is True:
        return {'value': 0, 'used_units': units, 'open_dependencies': []}
    if applies['value'] is False:
