def section_152_qualifying_child_relationship(facts):
    relationship = facts.get('individual_relationship_to_taxpayer')
    accepted = set([
        'child', 'descendant_of_child', 'brother', 'sister', 'stepbrother',
        'stepsister', 'descendant_of_brother_sister_stepbrother_or_stepsister'
    ])
    if relationship in accepted:
        return {'value': True, 'used_units': ['u152_c2_pred'], 'open_dependencies': []}
    return {'value': None, 'used_units': ['u152_c2_pred'], 'open_dependencies': ['individual_relationship_to_taxpayer']}

def section_152_qualifying_relative_relationship(facts):
    relationship = facts.get('individual_relationship_to_taxpayer')
    direct = set([
        'child', 'descendant_of_child', 'brother', 'sister', 'stepbrother',
        'stepsister', 'father', 'mother', 'ancestor_of_father_or_mother',
        'stepfather', 'stepmother', 'son_of_brother_or_sister',
        'daughter_of_brother_or_sister', 'brother_of_father_or_mother',
        'sister_of_father_or_mother', 'son_in_law', 'daughter_in_law',
        'father_in_law', 'mother_in_law', 'brother_in_law', 'sister_in_law'
    ])
    if relationship in direct:
        return {'value': True, 'used_units': ['u152_d2_pred'], 'open_dependencies': []}
    if relationship != 'household_member':
        return {'value': None, 'used_units': ['u152_d2_pred'], 'open_dependencies': ['individual_relationship_to_taxpayer']}
    same_abode = facts.get('same_principal_abode_for_entire_tax_year')
    household = facts.get('individual_is_member_of_taxpayer_household')
    was_spouse = facts.get('individual_was_taxpayer_spouse_at_any_time_during_tax_year')
    conditions = [
        same_abode if isinstance(same_abode, bool) else None,
        household if isinstance(household, bool) else None,
        (not was_spouse) if isinstance(was_spouse, bool) else None
    ]
    if False in conditions:
        return {'value': False, 'used_units': ['u152_d2_pred'], 'open_dependencies': []}
    if all(value is True for value in conditions):
        return {'value': True, 'used_units': ['u152_d2_pred'], 'open_dependencies': []}
    deps = []
    if not isinstance(same_abode, bool):
        deps.append('same_principal_abode_for_entire_tax_year')
    if not isinstance(household, bool):
        deps.append('individual_is_member_of_taxpayer_household')
    if not isinstance(was_spouse, bool):
        deps.append('individual_was_taxpayer_spouse_at_any_time_during_tax_year')
    return {'value': None, 'used_units': ['u152_d2_pred'], 'open_dependencies': deps}

def section_152_qualifying_child(facts):
    stipulated = facts.get('individual_is_qualifying_child_of_taxpayer_for_tax_year')
    if isinstance(stipulated, bool):
        return {'value': stipulated, 'used_units': ['u152_c1_pred'], 'open_dependencies': []}
    relationship = section_152_qualifying_child_relationship(facts)
    age = section_152_qualifying_child_age_requirement(facts)
    abode = facts.get('same_principal_abode_more_than_half_tax_year')
    joint = facts.get('individual_filed_joint_return_with_spouse')
    refund_only = facts.get('joint_return_was_only_for_refund_claim')
    if joint is False:
        joint_condition = True
        joint_deps = []
    elif joint is True and refund_only is True:
        joint_condition = True
        joint_deps = []
    elif joint is True and refund_only is False:
        joint_condition = False
        joint_deps = []
    elif joint is True:
        joint_condition = None
        joint_deps = ['joint_return_was_only_for_refund_claim']
    else:
        joint_condition = None
        joint_deps = ['individual_filed_joint_return_with_spouse']
    conditions = [relationship['value'], abode if isinstance(abode, bool) else None, age['value'], joint_condition]
    units = ['u152_c1_pred', 'u152_c2_pred', 'u152_c3_pred']
    if False in conditions:
        return {'value': False, 'used_units': units, 'open_dependencies': []}
    if all(value is True for value in conditions):
        return {'value': True, 'used_units': units, 'open_dependencies': []}
    deps = []
    if relationship['value'] is None:
        deps.extend(relationship['open_dependencies'])
    if not isinstance(abode, bool):
        deps.append('same_principal_abode_more_than_half_tax_year')
    if age['value'] is None:
        deps.extend(age['open_dependencies'])
    if joint_condition is None:
        deps.extend(joint_deps)
    return {'value': None, 'used_units': units, 'open_dependencies': sorted(set(deps))}

def section_152_dependent(facts):
    stipulated = facts.get('individual_is_dependent_of_taxpayer_for_tax_year')
    if isinstance(stipulated, bool):
        return {'value': stipulated, 'used_units': ['u152_a_pred'], 'open_dependencies': []}
    claimant_exception = section_152_dependent_claimant_ineligible(facts)
    married_exception = section_152_married_dependent_exception(facts)
    units = ['u152_a_pred', 'u152_b1_pred', 'u152_b2_pred', 'u152_c1_pred', 'u152_c2_pred', 'u152_c3_pred', 'u152_d1_pred', 'u152_d2_pred']
    if claimant_exception['value'] is True or married_exception['value'] is True:
        return {'value': False, 'used_units': units, 'open_dependencies': []}
    child = section_152_qualifying_child(facts)
    relative = section_152_qualifying_relative(facts)
    if child['value'] is False and relative['value'] is False:
        return {'value': False, 'used_units': units, 'open_dependencies': []}
    branch_true = child['value'] is True or relative['value'] is True
    if branch_true and claimant_exception['value'] is False and married_exception['value'] is False:
        return {'value': True, 'used_units': units, 'open_dependencies': []}
    deps = []
    if claimant_exception['value'] is None:
        deps.extend(claimant_exception['open_dependencies'])
    if married_exception['value'] is None:
        deps.extend(married_exception['open_dependencies'])
    if not branch_true:
        if child['value'] is None:
            deps.extend(child['open_dependencies'])
        if relative['value'] is None:
            deps.extend(relative['open_dependencies'])
    return {'value': None, 'used_units': units, 'open_dependencies': sorted(set(deps))}

def section_151_dependent_additional_exemption_qualifies(facts):
    stipulated = facts.get('individual_is_dependent_of_taxpayer_for_tax_year')
    units = ['u151_c_pred', 'u152_a_pred', 'u152_b1_pred', 'u152_b2_pred', 'u152_c1_pred', 'u152_c2_pred', 'u152_c3_pred', 'u152_d1_pred', 'u152_d2_pred']
    if isinstance(stipulated, bool):
        return {'value': stipulated, 'used_units': units, 'open_dependencies': []}
    result = section_152_dependent(facts)
    return {'value': result['value'], 'used_units': units, 'open_dependencies': result['open_dependencies']}
